// This file is hand written and is not regenerated by `go generate
// ./internal/ent`: it provides OpenDatabase, the one entry point every
// composition root uses to get a migrated ent Client, and the only place
// in this project that decides which database dialect a DSN names.
//
// Code generation only ever (re)writes files into this directory by fixed
// name and never scans it, so this file coexists safely with the
// generated ones, the same way embedded.go already does.
package ent

import (
	"context"
	stdsql "database/sql"
	"fmt"
	"strings"
	"time"

	entsql "entgo.io/ent/dialect/sql"

	"github.com/Subject-Void-LLC/the-pleiades/internal/ent/migrate"
)

// Config is what a composition root hands OpenDatabase.
//
// It is a struct wrapping a DSN rather than a bare string so that pool
// tuning can be added without changing every call site, and rather than a
// fully decomposed Config{Driver, Host, Port, User, Password, Database}
// because that would reinvent net/url and force every deployment surface
// (compose, Helm, the Dockerfiles, the getting-started guide) to grow six
// environment variables where one suffices.
//
// The honest cost of a DSN is that a typo is a runtime error rather than
// a compile error. OpenDatabase mitigates that by resolving the dialect up front
// and failing closed, with an error naming every scheme it does support,
// rather than guessing.
type Config struct {
	// DSN names the database. See OpenDatabase for the accepted forms.
	DSN string

	// MaxOpenConns bounds the connection pool. Zero means the
	// database/sql default of unlimited.
	MaxOpenConns int

	// MaxIdleConns bounds the idle pool. Zero means the database/sql
	// default.
	MaxIdleConns int

	// ConnMaxLifetime retires a connection after this long. Zero means
	// connections are reused forever, which is the database/sql default.
	ConnMaxLifetime time.Duration
}

// resolvedDSN is a Config.DSN after the dialect has been decided: the
// driver to open it with, the exact string that driver wants, and any
// work that has to happen before the driver is opened.
type resolvedDSN struct {
	// driver is the database/sql driver name. It doubles as the dialect
	// key internal/ent/migrate.Apply is indexed by, which is why there is
	// no second mapping to keep in step.
	driver string

	// dsn is the driver-specific data source name.
	dsn string

	// prepare runs before the driver is opened, for dialects that need
	// something to exist first. Nil when there is nothing to do.
	prepare func() error

	// describe names the database in error messages without leaking a
	// DSN's embedded credentials into a log line.
	describe string
}

// OpenDatabase opens an ent Client against the database named by cfg.DSN, applies
// every pending versioned migration, and returns the client ready for use.
//
// Accepted DSN forms:
//
//   - "postgres://user:pass@host:5432/db?sslmode=disable" (or the
//     "postgresql://" spelling): a real PostgreSQL server, which is what
//     a Walk-tier deployment runs.
//   - "sqlite://relative/path.db" or "sqlite:///absolute/path.db": an
//     on-disk SQLite file.
//   - a bare filesystem path, with no scheme at all: the same on-disk
//     SQLite file. This form exists so the older DB_PATH configuration
//     keeps working unchanged.
//
// A DSN carrying any other scheme is rejected rather than guessed at.
// Note the consequence of the bare-path rule: a PostgreSQL DSN must use
// URL form, because libpq's alternative keyword form ("host=... user=...")
// carries no scheme and would be indistinguishable from a filename.
//
// Migration is idempotent and fails closed: internal/ent/migrate.Apply
// records each committed migration file as it applies it, so calling
// OpenDatabase again against a database that already has every migration applied is a
// clean no-op, and calling it against one whose recorded history this
// binary's embedded migrations do not recognize (or that has a gap in an
// already-applied prefix) returns an error instead of silently proceeding
// against a schema shape that was never verified.
//
// The returned Client must be closed by the caller (Client.Close) once it
// is no longer needed.
func OpenDatabase(ctx context.Context, cfg Config) (*Client, error) {
	resolved, err := resolveDSN(cfg.DSN)
	if err != nil {
		return nil, err
	}

	if resolved.prepare != nil {
		if err := resolved.prepare(); err != nil {
			return nil, err
		}
	}

	// Open the raw driver first so the migration runner can run plain SQL
	// against it before any ent-generated query touches the connection.
	db, err := stdsql.Open(resolved.driver, resolved.dsn)
	if err != nil {
		return nil, fmt.Errorf("ent: opening database %s: %w", resolved.describe, err)
	}

	if cfg.MaxOpenConns > 0 {
		db.SetMaxOpenConns(cfg.MaxOpenConns)
	}
	if cfg.MaxIdleConns > 0 {
		db.SetMaxIdleConns(cfg.MaxIdleConns)
	}
	if cfg.ConnMaxLifetime > 0 {
		db.SetConnMaxLifetime(cfg.ConnMaxLifetime)
	}

	if err := migrate.Apply(ctx, resolved.driver, db); err != nil {
		// Close the half-opened database on the error path so its file
		// descriptor is not leaked back to the caller.
		if cerr := db.Close(); cerr != nil {
			return nil, fmt.Errorf("ent: migrating database %s: %w (also failed to close: %v)", resolved.describe, err, cerr)
		}
		return nil, fmt.Errorf("ent: migrating database %s: %w", resolved.describe, err)
	}

	// Wrap the same, already-migrated connection in the ent client rather
	// than opening a second one, so migration and every later query share
	// one connection pool against the same database.
	drv := entsql.OpenDB(resolved.driver, db)
	return NewClient(Driver(drv)), nil
}

// resolveDSN decides which dialect dsn names. It is the single place a
// scheme is turned into a driver, so no caller anywhere else in this
// project needs to know a driver name at all.
func resolveDSN(dsn string) (resolvedDSN, error) {
	switch {
	case strings.HasPrefix(dsn, postgresURLScheme), strings.HasPrefix(dsn, postgresqlURLScheme):
		return resolvePostgres(dsn), nil

	case strings.HasPrefix(dsn, sqliteURLScheme):
		return resolveSQLite(strings.TrimPrefix(dsn, sqliteURLScheme)), nil

	case strings.Contains(dsn, "://"):
		return resolvedDSN{}, fmt.Errorf("ent: unsupported database scheme in DSN; want one of %q, %q, %q, or a bare filesystem path for SQLite",
			postgresURLScheme, postgresqlURLScheme, sqliteURLScheme)

	default:
		// No scheme at all: a bare filesystem path naming a SQLite file.
		return resolveSQLite(dsn), nil
	}
}
